states.67252c9b4c99:
{
 "politika": [
  "Firma izleme kaydı ile ilgili tüm yazışmalar Yapılandırma Birimi ortak kutusuna kopyalanır.",
  "Ticari Bankacılık ile Kredi İzleme arasındaki devirler devir formu ile belgelenir.",
  "Kayıt üzerinde yapılan her değişiklik, değişikliği yapan kullanıcının adıyla günlüğe yazılır.",
  "Yönetici, izinli olduğu günlerde yetkisini yazılı olarak bir vekile devreder.",
  "Otomatik sistem her hafta açık firma izleme kaydı listesini gözden geçirir ve gerekirse not ekler.",
  "Süreçle ilgili eğitimler yılda en az bir kez tekrarlanır.",
  "Kişisel veriler yalnız işin gerektirdiği ölçüde görüntülenir ve paylaşılır.",
  "Bu süreçte kullanılan formların güncel sürümü kurum içi portalda yayımlanır.",
  "Firma izleme kaydı kapatılmadan önce tüm ekler okunabilirlik açısından kontrol edilir.",
  "Kayıtlarda kısaltma kullanılmaz; açıklamalar tam cümle olarak yazılır.",
  "Bugün planlanan iş «sonraki» sayılmaz; yalnız yarından itibaren olanlar sayılır."
 ],
 "kayit": {
  "no": "IZL-76673",
  "Bugünün tarihi": "28.04.2026"
 },
 "planlı işler": [
  {
   "İş": "yerinde kontrol",
   "Tarih": "13.04.2026"
  },
  {
   "İş": "müşteri görüşmesi",
   "Tarih": "04.05.2026"
  },
  {
   "İş": "denetim ziyareti",
   "Tarih": "22.05.2026"
  },
  {
   "İş": "sistem bakımı",
   "Tarih": "23.05.2026"
  }
 ],
 "notlar": [
  "Can Aydın, bir meslektaşının da benzer bir soru sorabileceğini söyledi.",
  "Hava yağmurlu olduğu için yüz yüze görüşme çevrim içi yapıldı.",
  "Kredi İzleme personeli için yeni bir bilgilendirme toplantısı planlanıyor.",
  "Yapılandırma Birimi yöneticisi haftalık değerlendirmeye katılamadı.",
  "Kayıt sahibine otomatik bir alındı bildirimi gönderildi.",
  "Cem Çetin ek açıklama yapmaya gerek görmediğini belirtti.",
  "Yusuf Erdem görüşme sonunda ilgili ekibe teşekkür etti.",
  "Ekipte iki yeni çalışan oryantasyona başladı.",
  "Sistem duyuruları ana sayfada güncellendi.",
  "Ofis taşınması nedeniyle bazı dosyalar geçici olarak başka kata alındı."
 ]
}

